//! The README status table (Phase 0 item 0.5).
//!
//! Every number in the table is collected by the checks themselves while they
//! run, never typed by hand. `cargo xtask verify` fails if the README's copy
//! differs from what the run measured, so the published numbers cannot drift
//! from reality.

use std::collections::BTreeMap;
use std::path::Path;
use std::process::Command;

use serde_json::Value;

use crate::conformance::{self, Suite};
use crate::workspace;

/// First line of the generated block in README.md.
pub const BEGIN: &str =
    "<!-- BEGIN STATUS: generated by `cargo xtask report --write`; do not edit by hand -->";
/// Last line of the generated block.
pub const END: &str = "<!-- END STATUS -->";
pub const README: &str = "README.md";

/// The host shell's source (phase-2.md item 2.15) and the line limit the plan
/// sets it.
pub const HOST_SHELL_DIR: &str = "crates/clazel/src";
pub const HOST_SHELL_LIMIT: usize = 300;
/// The network shell's source (phase-3.md item 3.8), counted like the host
/// shell. The plan sets it no limit.
pub const NET_SHELL_DIR: &str = "crates/clazel-net/src";

/// Lines (newline characters, as `wc -l` counts) in the Rust files under `dir`
/// (a shell's source), or `None` if there is no such directory.
pub fn shell_lines(dir: &Path) -> Option<Result<usize, String>> {
    if !dir.is_dir() {
        return None;
    }
    let count = || -> Result<usize, String> {
        let mut total = 0usize;
        for f in workspace::rust_files(dir)? {
            let text = std::fs::read_to_string(&f).map_err(|e| format!("{}: {e}", f.display()))?;
            total = total.saturating_add(text.matches('\n').count());
        }
        Ok(total)
    };
    Some(count())
}

/// Lines inside `verus!`, by kind, as counted by Verus's `line_count`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Lines {
    pub spec: u64,
    pub proof: u64,
    pub exec: u64,
}

/// Mutation counts, as in `mutate::Report`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Mutations {
    pub killed: usize,
    pub incidental: usize,
    pub survived: usize,
    pub total: usize,
}

/// What the run measured for one crate. `None` means "not measured in this
/// run", which makes the table incomplete.
#[derive(Debug, Default, Clone)]
pub struct Metrics {
    pub tier: Option<u64>,
    pub target_tier: Option<u64>,
    pub is_verus: bool,
    pub kani_harnesses: usize,
    pub axioms: usize,
    /// `unsafe` blocks and the lines they cover (only `clazel-sys` may have any).
    pub unsafe_blocks: usize,
    pub unsafe_lines: usize,
    /// Verus summary, e.g. "16 verified, 0 errors".
    pub verus: Option<String>,
    /// Kani summary, e.g. "3 successfully verified harnesses, 0 failures, 3 total".
    pub kani: Option<String>,
    pub lines: Option<Lines>,
    pub mutations: Option<Mutations>,
    /// Spec files reviewed and current, out of all reviewable files.
    pub reviews: Option<(usize, usize)>,
    /// Every suite the crate's `tests/conformance*.rs` reported, by name;
    /// empty if it has none.
    pub conformance: Option<Vec<Suite>>,
}

impl Metrics {
    /// Everything this crate's table row needs was measured.
    pub fn complete(&self) -> bool {
        let verus_ok = !self.is_verus
            || (self.verus.is_some() && self.lines.is_some() && self.mutations.is_some());
        let kani_ok = self.kani_harnesses == 0 || self.kani.is_some();
        verus_ok && kani_ok && self.reviews.is_some() && self.conformance.is_some()
    }
}

/// Metrics for every crate, keyed (and so ordered) by crate name.
pub type Table = BTreeMap<String, Metrics>;

/// The table's header and rule lines.
const HEADER: &str = "| Crate | Tier (target) | Verus | Kani | Axioms | `unsafe` blocks (lines)⁵ | Lines: spec / proof / exec¹ | Spec mutations: theorem / incidental / survived² | Conformance⁴ | Spec review³ |";
const RULE: &str = "|-------|---------------|-------|------|--------|--------------------------|-----------------------------|---------------------------------------------------|--------------|--------------|";

/// The columns a `--changed` run carries over from the committed table for
/// crates it did not select: Verus, Kani, lines, mutations and conformance,
/// the ones only a proof or test run measures. The others (tier, axioms,
/// `unsafe`, reviews) come from the static checks, which always run in
/// full, so they are measured afresh for every crate.
const CARRIED_COLUMNS: [usize; 5] = [2, 3, 6, 7, 8];

/// Cells of a committed table row, crate name first, keyed by crate name.
pub type Rows = BTreeMap<String, Vec<String>>;

/// The rows of a generated block. Fails if its header is not this
/// version's, because then its cells do not line up with the columns.
pub fn rows(block: &str) -> Result<Rows, String> {
    let mut lines = block.lines().skip(1);
    if lines.next() != Some(HEADER) || lines.next() != Some(RULE) {
        return Err(
            "README.md's table has another column layout; run the full report once".to_owned(),
        );
    }
    let mut out = Rows::new();
    for line in lines.take_while(|l| l.starts_with('|')) {
        let cells: Vec<String> = line
            .trim_matches('|')
            .split('|')
            .map(|c| c.trim().to_owned())
            .collect();
        if cells.len() != 10 {
            return Err(format!(
                "README.md table row has {} cells: {line}",
                cells.len()
            ));
        }
        if let Some(name) = cells.first() {
            out.insert(name.clone(), cells);
        }
    }
    Ok(out)
}

/// The generated block, markers included, with nothing carried over.
#[cfg(test)]
pub fn render(table: &Table) -> String {
    render_with(table, &Rows::new(), None, None)
}

/// The generated block, taking [`CARRIED_COLUMNS`] from `carried` for the
/// crates it has a row for, and every other cell from `table`. The caller
/// supplies the measured host- and network-shell counts; rendering performs
/// no I/O.
pub fn render_with(
    table: &Table,
    carried: &Rows,
    host_shell_count: Option<usize>,
    net_shell_count: Option<usize>,
) -> String {
    let dash = || "—".to_owned();
    let mut out = vec![BEGIN.to_owned(), HEADER.to_owned(), RULE.to_owned()];
    for (name, m) in table {
        let tier = match (m.tier, m.target_tier) {
            (Some(t), Some(target)) => format!("{t} ({target})"),
            _ => "undeclared".to_owned(),
        };
        let verus = if m.is_verus {
            m.verus.clone().unwrap_or_else(dash)
        } else {
            "not used".to_owned()
        };
        let kani = if m.kani_harnesses == 0 {
            "no harnesses".to_owned()
        } else {
            m.kani.clone().unwrap_or_else(dash)
        };
        let lines = m
            .lines
            .as_ref()
            .map_or_else(dash, |l| format!("{} / {} / {}", l.spec, l.proof, l.exec));
        let mutations = m.mutations.as_ref().map_or_else(dash, |x| {
            format!(
                "{} / {} / {} of {}",
                x.killed, x.incidental, x.survived, x.total
            )
        });
        let review = match m.reviews {
            Some((_, 0)) => "no spec files".to_owned(),
            Some((current, total)) => format!("{current} of {total} files current"),
            None => dash(),
        };
        let suites = m
            .conformance
            .as_deref()
            .map_or_else(dash, conformance::cell);
        let mut cells = vec![
            name.clone(),
            tier,
            verus,
            kani,
            m.axioms.to_string(),
            format!("{} ({})", m.unsafe_blocks, m.unsafe_lines),
            lines,
            mutations,
            suites,
            review,
        ];
        if let Some(old) = carried.get(name) {
            for i in CARRIED_COLUMNS {
                if let (Some(cell), Some(kept)) = (cells.get_mut(i), old.get(i)) {
                    cell.clone_from(kept);
                }
            }
        }
        out.push(format!("| {} |", cells.join(" | ")));
    }
    out.push(String::new());
    out.push(
        "¹ From Verus's `line_count`; only code inside `verus!` is counted, and type \
         definitions count as exec."
            .to_owned(),
    );
    out.push(
        "² Only the first number is coverage: a proven theorem is false for that many \
         deliberately broken specs. See [docs/VERIFICATION.md](docs/VERIFICATION.md#proof-mutation-testing)."
            .to_owned(),
    );
    out.push(
        "³ Optional human reviews of specs, contracts, axioms and mutation labels, \
         unchanged since review. They gate nothing; see \
         [docs/SPEC-REVIEWS.md](docs/SPEC-REVIEWS.md)."
            .to_owned(),
    );
    out.push(
        "⁴ Measured by the run: passing / total units per vendored suite, as each \
         `tests/conformance*.rs` reports them. Expected failures are counted \
         separately and never as passes. See \
         [docs/VERIFICATION.md](docs/VERIFICATION.md#honesty-metrics)."
            .to_owned(),
    );
    out.push(
        "⁵ Counted by `cargo xtask check`: `unsafe` blocks (and `unsafe extern` blocks), \
         with the lines from the `unsafe` keyword to the closing brace. Only \
         `clazel-sys` may have any; the rule and its audits are in \
         [docs/VERIFICATION.md](docs/VERIFICATION.md) and \
         [docs/SYS-AUDITS.md](docs/SYS-AUDITS.md)."
            .to_owned(),
    );
    if let Some(n) = host_shell_count {
        out.push(format!(
            "⁶ The host shell (`{HOST_SHELL_DIR}`, item 2.15) is {n} lines, counted as `wc -l` \
             counts them over its Rust files; the plan's limit is {HOST_SHELL_LIMIT}. The \
             command line and the demo (`crates/clazel/cli`, item 2.16) are not counted: \
             they only call the shell's public functions."
        ));
    }
    if let Some(n) = net_shell_count {
        out.push(format!(
            "⁷ The network shell (`{NET_SHELL_DIR}`, item 3.8: the resolver's sockets, TCP \
             connections and the loop that drives the fetch transducer) is {n} lines, counted \
             the same way. It is Tier 0 and makes no protocol decisions: every parser and \
             decision on its path is a proven function of the crates it calls."
        ));
    }
    out.push(END.to_owned());
    out.join("\n")
}

/// The generated block currently in `readme`, markers included.
pub fn current(readme: &str) -> Option<&str> {
    let start = readme.find(BEGIN)?;
    let end = readme.get(start..)?.find(END)?;
    readme.get(start..start.saturating_add(end).saturating_add(END.len()))
}

/// `readme` with its generated block replaced by `block`.
pub fn splice(readme: &str, block: &str) -> Result<String, String> {
    let old = current(readme).ok_or_else(|| format!("{README}: no {BEGIN} … {END} block"))?;
    Ok(readme.replacen(old, block, 1))
}

/// Count spec / proof / exec lines in a crate with the `line_count` tool
/// shipped next to the `verus` binary.
pub fn line_count(dir: &Path) -> Result<Lines, String> {
    let verus = which("verus").ok_or("verus not on PATH")?;
    let real = std::fs::canonicalize(&verus).map_err(|e| format!("{}: {e}", verus.display()))?;
    let tool = real.with_file_name("line_count");
    let files = workspace::rust_files(dir)?;
    let out = Command::new(&tool)
        .arg("--json")
        .args(&files)
        .output()
        .map_err(|e| format!("cannot run {}: {e}", tool.display()))?;
    if !out.status.success() {
        return Err(format!(
            "line_count failed:\n{}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    let json: Value = serde_json::from_slice(&out.stdout)
        .map_err(|e| format!("line_count output is not JSON: {e}"))?;
    let total = json.get("total").ok_or("line_count: no total")?;
    let get = |k: &str| total.get(k).and_then(Value::as_u64).unwrap_or(0);
    Ok(Lines {
        spec: get("spec"),
        proof: get("proof"),
        exec: get("exec"),
    })
}

/// Full path of `bin` on PATH.
pub fn which(bin: &str) -> Option<std::path::PathBuf> {
    let paths = std::env::var_os("PATH")?;
    std::env::split_paths(&paths)
        .map(|d| d.join(bin))
        .find(|p| p.is_file())
}

#[cfg(test)]
mod tests {
    use super::{
        BEGIN, END, Lines, Metrics, Mutations, Table, current, render, render_with, rows, splice,
    };

    #[test]
    fn splice_replaces_only_the_block() -> Result<(), String> {
        let readme = format!("intro\n{BEGIN}\nold\n{END}\noutro\n");
        let mut t = Table::new();
        t.insert(
            "a".into(),
            Metrics {
                tier: Some(0),
                target_tier: Some(0),
                reviews: Some((0, 0)),
                conformance: Some(Vec::new()),
                ..Metrics::default()
            },
        );
        let block = render(&t);
        let new = splice(&readme, &block)?;
        assert!(new.starts_with("intro\n") && new.ends_with("\noutro\n"));
        assert_eq!(current(&new), Some(block.as_str()));
        assert!(new.contains(
            "| a | 0 (0) | not used | no harnesses | 0 | 0 (0) | — | — | none | no spec files |"
        ));
        assert!(!block.contains("⁶ The host shell"));
        assert!(!block.contains("⁷ The network shell"));
        let with_shell = render_with(&t, &super::Rows::new(), Some(298), Some(1805));
        assert!(with_shell.contains("is 298 lines, counted as `wc -l`"));
        assert!(with_shell.contains("is 1805 lines, counted the same way"));
        Ok(())
    }

    #[test]
    fn carried_rows_keep_only_the_measured_columns() -> Result<(), String> {
        let measured = Metrics {
            tier: Some(2),
            target_tier: Some(2),
            is_verus: true,
            axioms: 1,
            verus: Some("5 verified, 0 errors".into()),
            lines: Some(Lines {
                spec: 1,
                proof: 2,
                exec: 3,
            }),
            mutations: Some(Mutations {
                killed: 4,
                incidental: 0,
                survived: 0,
                total: 4,
            }),
            reviews: Some((0, 2)),
            conformance: Some(Vec::new()),
            ..Metrics::default()
        };
        let mut t = Table::new();
        t.insert("a".into(), measured.clone());
        let old = rows(&render(&t))?;
        assert_eq!(old.get("a").map(Vec::len), Some(10));
        // A later run that measured nothing expensive, with a review added
        // and the tier raised: carried cells come from `old`, the rest is new.
        let mut later = Table::new();
        later.insert(
            "a".into(),
            Metrics {
                tier: Some(2),
                target_tier: Some(2),
                is_verus: true,
                axioms: 1,
                reviews: Some((1, 2)),
                ..Metrics::default()
            },
        );
        let block = render_with(&later, &old, None, None);
        assert!(block.contains(
            "| a | 2 (2) | 5 verified, 0 errors | no harnesses | 1 | 0 (0) | 1 / 2 / 3 | 4 / 0 / 0 of 4 | none | 1 of 2 files current |"
        ));
        // Round trip: rendering the full measurement again changes nothing.
        assert_eq!(render_with(&t, &old, None, None), render(&t));
        Ok(())
    }

    #[test]
    fn rows_reject_another_layout() {
        let old = format!("{BEGIN}\n| Crate | Tier |\n|---|---|\n| a | 0 |\n{END}");
        assert!(rows(&old).is_err());
    }

    #[test]
    fn incomplete_when_verus_crate_unmeasured() {
        let m = Metrics {
            is_verus: true,
            ..Metrics::default()
        };
        assert!(!m.complete());
        let plain = Metrics {
            reviews: Some((0, 0)),
            ..Metrics::default()
        };
        assert!(!plain.complete(), "conformance not measured");
        let plain = Metrics {
            conformance: Some(Vec::new()),
            ..plain
        };
        assert!(plain.complete());
    }
}
